mapper.select:

WHERE a.asgn_stts_cd!='CANCELLED' AND a.bgn_dt <= #{last} AND a.end_dt >= #{first}
AND a.prj_id=#{projectId}
AND a.job_cd=#{job}
AND (position(lower(#{q}) in lower(d.dev_nm))>0 OR position(lower(#{q}) in lower(d.mng_no))>0)
ORDER BY a.asgn_id

SELECT EXISTS(SELECT 1 FROM mst.dev_work_stts_hist h WHERE h.dev_id=#{developer}
  AND h.work_stts_cd IN ('VACATION','PARENTAL','UNPAID','LEAVE')
  AND h.bgn_dt <= #{end} AND (h.end_dt IS NULL OR h.end_dt >= #{start}))

SELECT EXISTS(SELECT 1 FROM asgn.asgn a WHERE a.prj_id=#{project} AND a.dev_id=#{developer}
  AND a.asgn_stts_cd!='CANCELLED' AND a.bgn_dt <= #{end} AND a.end_dt >= #{start}
  AND a.asgn_id!=#{excluded})
